import os

# 사용자로부터 경로 입력 받기
folder_path = input('삭제할 폴더 경로를 입력하세요: ')

# 폴더가 존재하는지 확인
if os.path.exists(folder_path):
    # 폴더 내부 파일 목록 가져오기
    files = [os.path.join(folder_path, f) for f in os.listdir(folder_path) if os.path.isfile(os.path.join(folder_path, f))]

    if files:
        print('다음 파일들이 삭제됩니다:')
        for file in files:
            print(f'- {file}')

        # 삭제 실행
        for file in files:
            os.remove(file)
            print(f'{file} 파일이 삭제되었습니다.')
        print('모든 파일이 삭제되었습니다.')
    else:
        print('폴더가 비어 있습니다.')
else:
    print('지정된 폴더가 존재하지 않습니다.')
